#ifndef AWK_HPP
#define AWK_HPP
#include <algorithm>
#include <cstdint>
#include <fstream>
#include <functional>
#include <iomanip>
#include <iterator>
#include <map>
#include <memory>
#include <optional>
#include <set>
#include <sstream>
#include <string>
#include <tuple>
#include <utility>
#include <vector>
namespace awk {
    using Integer = std::int64_t;
    struct Position {
        int line = 1, column = 1;
        bool operator <(const Position& other) const {return std::tie(line, column) < std::tie(other.line, other.column);
        } std::string text() const {return std::to_string(line) + ":" + std::to_string(column);
        }
    };
    struct Issue {
        Position position;
        std::string message;
        int kind = 0;
    };
    struct Token {
        std::string kind, text, value;
        Position position;
    };
    std::vector<Token> tokenize(const std::string& source);
    bool letter(char c);
    bool digit(char c);
    struct Value {
        enum class Kind {Uninitialized, Number, String, NumericString};
        Kind kind = Kind::Uninitialized;
        Integer numeric = 0;
        std::string text;
        static Value number(Integer number);
        static Value string(const std::string& text);
        static Value input(const std::string& text);
        Integer to_number() const;
        std::string to_string() const;
        bool truth() const;
        std::string describe() const;
    };
    int compare(const Value& a, const Value& b);
    bool subscript_less(const std::string& a, const std::string& b);
    std::vector<std::string> split_pieces(const std::string& text, const std::string& separator);
    struct Record {
        Value zero = Value::string("");
        std::vector<Value> fields;
        std::function<Value(const std::string&)> special;
        explicit Record(std::function<Value(const std::string&)> read) : special(std::move(read)) {
        }
        void set(const std::string& text);
        Value read(Integer index) const;
        void write(Integer index, const Value& value);
        void resize(Integer size);
        void rebuild();
    };
    using Binding = std::pair<int, std::string>;
    struct Node;
    using NodePtr = std::shared_ptr < Node >;
    struct Node {
        std::string kind, text, flavor, redirect;
        Position position, name_position, redirect_position;
        NodePtr a, b, c, d;
        std::vector<NodePtr> nodes;
        bool flag = false;
        Integer number = 0;
        Binding binding = {-1, ""};
        int target = -1;
        std::int64_t count = 0, calls = 0;
        int active = 0, depth = 0;
        bool inside = false;
    };
    NodePtr node(const std::string& kind, const Position& position);
    std::vector<NodePtr> children(const NodePtr& value);
    bool is_lvalue(const NodePtr& value);
    class Parser {
        std::vector<Token> tokens;
        std::size_t index = 0;
        bool in_function = false;
        std::string phase;
        int loop_depth = 0;
        const Token& peek() const;
        Token take();
        bool accept(const std::string& spelling);
        Token expect(const std::string& spelling);
        [[noreturn]]void fail() const;
        void newlines();
        NodePtr name();
        NodePtr block();
        NodePtr statement();
        NodePtr condition();
        NodePtr loop_body();
        void terminator();
        NodePtr output(Token token);
        bool parenthesized_output() const;
        std::vector<NodePtr> expression_list(bool greater = true);
        NodePtr expression(bool greater = true);
        NodePtr conditional(bool greater);
        NodePtr logical(int level, bool greater);
        NodePtr membership(bool greater);
        NodePtr comparison(bool greater);
        NodePtr concatenation();
        NodePtr additive();
        NodePtr multiplicative();
        NodePtr unary();
        NodePtr postfix();
        NodePtr prefix();
        NodePtr lvalue();
        NodePtr atom();
        NodePtr binary(Token op, NodePtr a, NodePtr b);
        public:
        explicit Parser(std::vector<Token> input) : tokens(std::move(input)) {
        }
        std::vector<NodePtr> parse();
    };
    Value arithmetic(const std::string& operation, const Value& a, const Value& b, Position position);
    std::string format_output(const std::vector<Value>& values, Position position);
    Value invoke(const std::string& name, const std::vector<Value>& values, Position position);
    struct InputOperand {
        bool file = false;
        std::string name, value;
        Integer records = 0;
    };
    struct Arguments {
        std::vector<std::pair<std::string, std::string>> options;
        std::vector<InputOperand> operands;
    };
    Arguments parse_arguments(const std::string& text);
    bool valid_filename(const std::string& name);
    std::vector<std::string> read_records(const std::string& name);
    std::string read_file(const std::string& path);
    struct Output {
        bool open = false;
        Integer writes = 0;
        std::string content;
    };
    struct GetlineInput {
        bool open = false, ever = false;
        std::vector<std::string> lines;
        std::size_t position = 0;
        Integer reads = 0;
    };
    struct Streams {
        Output standard;
        std::map<std::string, Output> outputs;
        std::map<std::string, GetlineInput> inputs;
        std::vector<std::string> output_order, input_order;
        void write(const std::string& text, const std::optional<std::string>& name = {}, const std::string& mode = "", Position position = {});
        std::pair<int, std::string> getline(const std::string& name);
        int close(const std::string& name);
        void save() const;
    };
}
#endif

#include "awk.hpp"
namespace awk {
    Value arithmetic(const std::string& op, const Value& first, const Value& second, Position position) {
        Integer a = first.to_number(), b = second.to_number(), value = 0;
        if (op == "/" || op == "%") {
            if (b == 0) throw Issue {position, "division by zero", 2};
            value = op == "/" ? a/b : a%b;
        } else if (op == "^") {
            if (b < 0) throw Issue {position, "negative exponent", 2};
            value = 1;
            while (b) {
                if (b & 1) value *= a;
                b /= 2;
                if (b) a *= a;
            }
        } else if (op == "+") value = a + b;
        else if (op == "-") value = a - b;
        else value = a * b;
        return Value::number(value);
    }
    std::string format_output(const std::vector<Value>& values, Position position) {
        std::string fmt = values[0].to_string(), result;
        std::size_t i = 0, argument = 1;
        while (i < fmt.size()) {
            if (fmt[i] != '%') {
                result.push_back(fmt[i++]);
                continue;
            }
            ++i;
            if (i < fmt.size() && fmt[i] == '%') {
                result.push_back('%');
                ++i;
                continue;
            }
            bool left = false, zero = false;
            while (i < fmt.size() &&(fmt[i] == '-' || fmt[i] == '0')) {
                left = left || fmt[i] == '-';
                zero = zero || fmt[i] == '0';
                ++i;
            }
            int width = 0;
            while (i < fmt.size() && digit(fmt[i])) width = width * 10 + fmt[i++] - '0';
            std::optional<int> precision;
            if (i < fmt.size() && fmt[i] == '.') {
                ++i;
                precision = 0;
                while (i < fmt.size() && digit(fmt[i])) * precision = *precision * 10 + fmt[i++] - '0';
            }
            if (i == fmt.size() || std::string("discxo").find(fmt[i]) == std::string::npos) throw Issue {position, "invalid format", 2};
            char conversion = fmt[i++];
            if (argument == values.size()) throw Issue {position, "not enough arguments", 2};
            const Value& value = values[argument++];
            std::string body;
            bool numeric = std::string("dixo").find(conversion) != std::string::npos;
            if (numeric) {
                Integer n = value.to_number(), m = n < 0 ? -n : n;
                int base = conversion == 'x' ? 16 : conversion == 'o' ? 8 : 10;
                std::string digits;
                do {
                    digits.push_back("0123456789abcdef"[m%base]);
                    m /= base;
                } while (m);
                std::reverse(digits.begin(), digits.end());
                if (precision) {
                    if (*precision == 0 && n == 0) digits.clear();
                    else if (digits.size() < static_cast<std::size_t>(*precision)) digits.insert(0, *precision - digits.size(), '0');
                }
                body =(n < 0 ? "-" : "") + digits;
            } else if (conversion == 's') {
                body = value.to_string();
                if (precision && body.size() > static_cast<std::size_t>(*precision)) body.resize(*precision);
            } else if (value.kind == Value::Kind::Number || value.kind == Value::Kind::NumericString) {
                Integer code = value.to_number();
                if (code != 10 &&(code < 32 || code > 126)) throw Issue {position, "invalid character code", 2};
                body.push_back(static_cast<char>(code));
            } else {
                body = value.to_string().substr(0, 1);
            }
            if (width > static_cast<int>(body.size())) {
                std::size_t missing = width - body.size();
                if (left) body.append(missing, ' ');
                else if (numeric && zero && !precision) body.insert(!body.empty() && body[0] == '-' ? 1 : 0, missing, '0');
                else body.insert(0, missing, ' ');
            }
            result += body;
        }
        return result;
    }
    Value invoke(const std::string& name, const std::vector<Value>& v, Position position) {
        if (name == "sprintf") return Value::string(format_output(v, position));
        if (name == "int") return Value::number(v[0].to_number());
        std::string s = v[0].to_string();
        if (name == "substr") {
            Integer start = v[1].to_number(), end = v.size() == 3 ? start + v[2].to_number() : static_cast<Integer>(s.size()) + 1;
            start = std::max < Integer >(1, start);
            end = std::min < Integer >(end, static_cast<Integer>(s.size()) + 1);
            return Value::string(end > start ? s.substr(static_cast<std::size_t>(start - 1), static_cast<std::size_t>(end - start)) : "");
        }
        if (name == "index") {
            std::string sought = v[1].to_string();
            std::size_t at = s.find(sought);
            return Value::number(sought.empty() || at == std::string::npos ? 0 : static_cast<Integer>(at + 1));
        }
        for (char& c : s) {
            if (name == "toupper" && c >= 'a' && c <= 'z') c = static_cast<char>(c - 'a' + 'A');
            else if (name == "tolower" && c >= 'A' && c <= 'Z') c = static_cast<char>(c - 'A' + 'a');
        }
        return Value::string(s);
    }
}

#include "awk.hpp"
namespace awk {
    bool letter(char c) {
        return(c >= 'a' && c <= 'z') ||(c >= 'A' && c <= 'Z') || c == '_';
    }
    bool digit(char c) {
        return c >= '0' && c <= '9';
    }
    std::vector<Token> tokenize(const std::string& source) {
        const std::set<std::string> keywords = {"BEGIN", "END", "function", "if", "else", "while", "for", "do", "break", "continue", "next", "exit", "return", "delete", "in", "getline", "print", "printf"};
        const std::set<std::string> builtins = {"length", "substr", "index", "split", "sprintf", "toupper", "tolower", "close", "int"};
        const std::set<std::string> pairs = {"+=", "-=", "*=", "/=", "%=", "^=", "==", "<=", ">=", "!=", "++", "--", "&&", "||", ">>"};
        const std::map<char, char> escapes = { {'n', '\n'}, {'t', '\t'}, {'\\', '\\'}, {'"', '"'}, {'/', '/'} };
        std::vector<Token> result;
        std::size_t i = 0;
        Position position;
        while (i < source.size()) {
            char c = source[i];
            Position start = position;
            if (c == ' ') {
                ++i;
                ++position.column;
                continue;
            }
            if (c == '\\' && i + 1 < source.size() && source[i + 1] == '\n') {
                i += 2;
                ++position.line;
                position.column = 1;
                continue;
            }
            if (c == '#') {
                while (i < source.size() && source[i] != '\n') {
                    ++i;
                    ++position.column;
                }
                continue;
            }
            if (c == '\n') {
                result.push_back({"newline", "\n", "", start});
                ++i;
                ++position.line;
                position.column = 1;
                continue;
            }
            std::size_t end = i + 1;
            std::string kind, value;
            if (digit(c)) {
                while (end < source.size() && digit(source[end]))++end;
                kind = "number";
                value = source.substr(i, end - i);
            } else if (letter(c)) {
                while (end < source.size() &&(letter(source[end]) || digit(source[end])))++end;
                std::string word = source.substr(i, end - i);
                kind = keywords.count(word) ? "keyword" : builtins.count(word) ? "builtin" : end < source.size() && source[end] == '(' ? "function_name" : "name";
            } else if (c == '"') {
                while (end < source.size() && source[end] != '"') {
                    if (source[end] == '\n') throw Issue {start, "", 0};
                    if (source[end] == '\\') {
                        if (end + 1 >= source.size() || !escapes.count(source[end + 1])) throw Issue { {position.line, position.column + static_cast<int>(end - i)}, "", 0};
                        value.push_back(escapes.at(source[end + 1]));
                        end += 2;
                    } else value.push_back(source[end++]);
                }
                if (end == source.size()) throw Issue {start, "", 0};
                ++end;
                kind = "string";
            } else if (pairs.count(source.substr(i, 2))) {
                ++end;
                kind = "symbol";
            } else if (std::string("+-*/%^!><?:=()[]{},;$").find(c) != std::string::npos) kind = "symbol";
            else throw Issue {start, "", 0};
            result.push_back({kind, source.substr(i, end - i), value, start});
            position.column += static_cast<int>(end - i);
            i = end;
        }
        result.push_back({"end", "", "", {static_cast<int>(std::count(source.begin(), source.end(), '\n')) + 1, 1} });
        return result;
    }
}

#include "awk.hpp"
namespace awk {
    struct Analysis {
        std::vector<NodePtr> items, functions, rules, nodes;
        std::map<std::string, int> function_table;
        std::set<Binding> bindings, arrays;
        std::set<std::string> globals = {"FILENAME", "FNR", "FS", "NF", "NR", "OFS", "ORS", "SUBSEP"};
        std::set<int> lines;
        struct Error {
            Position position;
            int priority;
            std::string text;
        };
        std::vector<Error> errors;
        explicit Analysis(std::vector<NodePtr> values) : items(std::move(values)) {
            for (const std::string& name : globals) bindings.emplace(-1, name);
            for (const NodePtr& item : items) if (item->kind == "function") {
                int id = static_cast<int>(functions.size());
                if (function_table.count(item->text)) errors.push_back({item->name_position, 0, "function " + item->text + " redefined"});
                else function_table[item->text] = id;
                functions.push_back(item);
                std::set<std::string> names;
                for (const NodePtr& p : item->nodes) if (!names.insert(p->text).second) errors.push_back({p->position, 1, "duplicate parameter " + p->text});
            } else rules.push_back(item);
            const std::set<std::string> statements = {"if", "while", "do", "for", "for_in", "print", "printf", "delete", "next", "break", "continue", "exit", "return", "expression_statement"};
            int function_id = 0;
            for (const NodePtr& item : items) {
                int scope = -1;
                std::set<std::string> parameters;
                if (item->kind == "function") {
                    scope = function_id++;
                    for (const NodePtr& p : item->nodes) parameters.insert(p->text);
                }
                std::vector<NodePtr> pending = {item};
                while (!pending.empty()) {
                    NodePtr n = pending.back();
                    pending.pop_back();
                    nodes.push_back(n);
                    if (statements.count(n->kind)) lines.insert(n->position.line);
                    if (n->kind == "name" || n->kind == "array" || n->kind == "parameter") {
                        int resolved = scope >= 0 && parameters.count(n->text) ? scope : -1;
                        n->binding = {resolved, n->text};
                        bindings.insert(n->binding);
                        if (resolved < 0) globals.insert(n->text);
                        if (function_table.count(n->text)) errors.push_back({n->position, 2, "function " + n->text + " used as variable"});
                    }
                    if (n->kind == "call") {
                        if (!function_table.count(n->text)) errors.push_back({n->position, 3, "undefined function " + n->text});
                        else {
                            n->target = function_table[n->text];
                            if (n->nodes.size() > functions[n->target]->nodes.size()) errors.push_back({n->position, 4, "too many arguments to " + n->text});
                        }
                    }
                    std::vector<NodePtr> cs = children(n);
                    pending.insert(pending.end(), cs.rbegin(), cs.rend());
                }
            }
            if (!errors.empty()) {
                std::sort(errors.begin(), errors.end(),[](const Error& a, const Error& b) {
                    return std::tie(a.position.line, a.position.column, a.priority) < std::tie(b.position.line, b.position.column, b.priority);
                });
                throw Issue {errors[0].position, errors[0].text, 1};
            }
            std::vector<std::pair<Binding, Binding>> links;
            for (const NodePtr& n : nodes) {
                if (n->kind == "array") arrays.insert(n->binding);
                else if (n->kind == "membership" || n->kind == "delete") arrays.insert(n->a->binding);
                else if (n->kind == "for_in") arrays.insert(n->b->binding);
                else if (n->kind == "builtin" && n->text == "split") arrays.insert(n->nodes[1]->binding);
                else if (n->kind == "call") for (std::size_t i = 0;i < n->nodes.size();++i) if (n->nodes[i]->kind == "name") links.emplace_back(n->nodes[i]->binding, functions[n->target]->nodes[i]->binding);
            }
            bool changed = true;
            while (changed) {
                changed = false;
                for (const auto& link : links) if (arrays.count(link.first) || arrays.count(link.second)) {
                    changed = arrays.insert(link.first).second || changed;
                    changed = arrays.insert(link.second).second || changed;
                }
            }
        }
    };
    using Array = std::map<std::string, Value>;
    struct Cell {
        Value scalar;
        std::shared_ptr < Array > array;
    };
    using CellPtr = std::shared_ptr < Cell >;
    struct Location {
        CellPtr cell;
        std::shared_ptr < Array > array;
        std::string key;
        Integer field = -1;
        bool nf = false;
    };
    struct Transfer {
        std::string kind;
        Value value;
    };
    class Engine {
        Analysis& analysis;
        Arguments arguments;
        std::map<std::string, CellPtr> globals;
        std::vector<std::map<std::string, CellPtr>> locals;
        std::map<int, Integer> line_counts;
        Record record;
        Streams streams;
        std::string phase = "BEGIN";
        Integer exit_status = 0;
        std::optional<Issue> error;
        std::size_t operand_position = 0, input_position = 0;
        InputOperand* current = nullptr;
        std::vector<std::string> input_lines;
        CellPtr cell(const Binding& binding) {
            if (binding.first >= 0) return locals.back().at(binding.second);
            CellPtr& value = globals[binding.second];
            if (!value) value = std::make_shared < Cell >();
            return value;
        }
        Value global(const std::string& name) {
            return name == "NF" ? Value::number(static_cast<Integer>(record.fields.size())) : cell({-1, name})->scalar;
        }
        std::shared_ptr < Array > array(const Binding& binding) {
            CellPtr value = cell(binding);
            if (!value->array) value->array = std::make_shared < Array >();
            return value->array;
        }
        void assign_input(const std::string& name, const std::string& text) {
            analysis.globals.insert(name);
            cell({-1, name})->scalar = Value::input(text);
        }
        std::string subscript(const std::vector<NodePtr>& expressions) {
            std::vector<std::string> values;
            for (const NodePtr& e : expressions) values.push_back(evaluate(e).to_string());
            std::string separator = global("SUBSEP").to_string(), key;
            for (std::size_t i = 0;i < values.size();++i) {
                if (i) key += separator;
                key += values[i];
            }
            return key;
        }
        Location location(const NodePtr& n) {
            Location result;
            if (n->kind == "name") {
                result.cell = cell(n->binding);
                result.nf = n->binding.first < 0 && n->text == "NF";
            } else if (n->kind == "array") {
                result.key = subscript(n->nodes);
                result.array = array(n->binding);
            } else {
                result.field = evaluate(n->a).to_number();
                if (result.field < 0) throw Issue {n->position, "negative field index", 2};
            }
            return result;
        }
        Value read(const Location& l) {
            if (l.field >= 0) return record.read(l.field);
            if (l.array) return(*l.array)[l.key];
            if (l.nf) return global("NF");
            return l.cell->scalar;
        }
        void store(const Location& l, const Value& value, Position position) {
            if (l.field >= 0) record.write(l.field, value);
            else if (l.array)(*l.array)[l.key] = value;
            else if (l.nf) {
                Integer size = value.to_number();
                if (size < 0) throw Issue {position, "negative NF", 2};
                record.resize(size);
            } else l.cell->scalar = value;
        }
        Value call(const NodePtr& n) {
            NodePtr f = analysis.functions[n->target];
            std::map<std::string, CellPtr> frame;
            for (std::size_t i = 0;i < f->nodes.size();++i) {
                NodePtr p = f->nodes[i];
                CellPtr value = std::make_shared < Cell >();
                if (analysis.arrays.count(p->binding)) value->array = i < n->nodes.size() ? array(n->nodes[i]->binding) : std::make_shared < Array >();
                else if (i < n->nodes.size()) value->scalar = evaluate(n->nodes[i]);
                frame[p->text] = value;
            }
            ++f->calls;
            ++f->active;
            f->depth = std::max(f->depth, f->active);
            locals.push_back(std::move(frame));
            Value result;
            try {
                statement(f->a);
            } catch (const Transfer& transfer) {
                locals.pop_back();
                --f->active;
                if (transfer.kind == "return") return transfer.value;
                throw;
            } catch (...) {
                locals.pop_back();
                --f->active;
                throw;
            }
            locals.pop_back();
            --f->active;
            return result;
        }
        Value builtin(const NodePtr& n) {
            const std::vector<NodePtr>& args = n->nodes;
            if (n->text == "length") {
                if (args.empty()) return Value::number(record.zero.to_string().size());
                if (args[0]->kind == "name" && analysis.arrays.count(args[0]->binding)) return Value::number(array(args[0]->binding)->size());
                return Value::number(evaluate(args[0]).to_string().size());
            }
            if (n->text == "split") {
                std::string text = evaluate(args[0]).to_string();
                std::string separator = args.size() == 3 ? evaluate(args[2]).to_string() : global("FS").to_string();
                std::shared_ptr < Array > destination = array(args[1]->binding);
                destination->clear();
                std::vector<std::string> pieces = split_pieces(text, separator);
                for (std::size_t i = 0;i < pieces.size();++i)(*destination)[std::to_string(i + 1)] = Value::input(pieces[i]);
                return Value::number(pieces.size());
            }
            if (n->text == "close") {
                std::string filename = evaluate(args[0]).to_string();
                return Value::number(streams.close(filename));
            }
            std::vector<Value> values;
            for (const NodePtr& arg : args) values.push_back(evaluate(arg));
            return invoke(n->text, values, n->position);
        }
        Value getline(const NodePtr& n) {
            std::pair<int, std::string> result;
            if (n->b) {
                std::string filename = evaluate(n->b).to_string();
                result = streams.getline(filename);
            } else if (phase == "END") return Value::number(0);
            else {
                std::optional<std::string> line = next_record();
                result = {line ? 1 : 0, line ? *line : ""};
            }
            if (result.first == 1) {
                if (n->a) {
                    Location target = location(n->a);
                    store(target, Value::input(result.second), n->position);
                } else record.set(result.second);
            }
            return Value::number(result.first);
        }
        Value evaluate(const NodePtr& n) {
            const std::string& kind = n->kind;
            if (kind == "number") return Value::number(n->number);
            if (kind == "string") return Value::string(n->text);
            if (is_lvalue(n)) return read(location(n));
            if (kind == "paren") return evaluate(n->a);
            if (kind == "assignment") {
                Location target = location(n->a);
                Value value = evaluate(n->b);
                if (n->text != "=") value = arithmetic(n->text.substr(0, 1), read(target), value, n->position);
                store(target, value, n->position);
                return read(target);
            }
            if (kind == "increment") {
                Location target = location(n->a);
                Integer old = read(target).to_number(), value = old + n->number;
                store(target, Value::number(value), n->position);
                return Value::number(n->flag ? value : old);
            }
            if (kind == "conditional") {
                bool condition = evaluate(n->a).truth();
                return evaluate(condition ? n->b : n->c);
            }
            if (kind == "unary") {
                Value value = evaluate(n->a);
                if (n->text == "!") return Value::number(!value.truth());
                return Value::number(n->text == "-" ? -value.to_number() : value.to_number());
            }
            if (kind == "membership") {
                std::string key = subscript(n->nodes);
                return Value::number(array(n->a->binding)->count(key));
            }
            if (kind == "binary") {
                Value a = evaluate(n->a);
                const std::string& op = n->text;
                if (op == "||" && a.truth()) return Value::number(1);
                if (op == "&&" && !a.truth()) return Value::number(0);
                Value b = evaluate(n->b);
                if (op == "&&" || op == "||") return Value::number(b.truth());
                if (op == "concat") return Value::string(a.to_string() + b.to_string());
                int order = compare(a, b);
                if (op == "<") return Value::number(order < 0);
                if (op == "<=") return Value::number(order <= 0);
                if (op == "==") return Value::number(order == 0);
                if (op == "!=") return Value::number(order != 0);
                if (op == ">=") return Value::number(order >= 0);
                if (op == ">") return Value::number(order > 0);
                return arithmetic(op, a, b, n->position);
            }
            if (kind == "call") return call(n);
            if (kind == "builtin") return builtin(n);
            return getline(n);
        }
        void output(const NodePtr& n) {
            std::vector<Value> values;
            for (const NodePtr& e : n->nodes) values.push_back(evaluate(e));
            std::string text;
            if (n->kind == "print") {
                if (values.empty()) values.push_back(record.zero);
                std::string separator = global("OFS").to_string();
                for (std::size_t i = 0;i < values.size();++i) {
                    if (i) text += separator;
                    text += values[i].to_string();
                }
                text += global("ORS").to_string();
            } else text = format_output(values, n->position);
            std::optional<std::string> filename;
            if (n->a) filename = evaluate(n->a).to_string();
            streams.write(text, filename, n->redirect, n->redirect_position);
        }
        bool loop_body(const NodePtr& body) {
            try {
                statement(body);
            } catch (const Transfer& t) {
                if (t.kind == "break") return false;
                if (t.kind != "continue") throw;
            }
            return true;
        }
        void statement(const NodePtr& n) {
            const std::string& kind = n->kind;
            if (kind == "block") {
                for (const NodePtr& s : n->nodes) statement(s);
                return;
            }
            if (kind == "empty") return;
            ++line_counts[n->position.line];
            if (kind == "expression_statement") evaluate(n->a);
            else if (kind == "print" || kind == "printf") output(n);
            else if (kind == "if") {
                NodePtr branch = evaluate(n->a).truth() ? n->b : n->c;
                if (branch) statement(branch);
            } else if (kind == "while") {
                while (evaluate(n->a).truth()) if (!loop_body(n->b)) break;
            } else if (kind == "do") {
                do {
                    if (!loop_body(n->b)) break;
                } while (evaluate(n->a).truth());
            } else if (kind == "for") {
                if (n->a) evaluate(n->a);
                while (!n->b || evaluate(n->b).truth()) {
                    if (!loop_body(n->d)) break;
                    if (n->c) evaluate(n->c);
                }
            } else if (kind == "for_in") {
                std::vector<std::string> keys;
                for (const auto& entry : *array(n->b->binding)) keys.push_back(entry.first);
                std::sort(keys.begin(), keys.end(), subscript_less);
                for (const std::string& key : keys) {
                    Location target = location(n->a);
                    store(target, Value::input(key), n->a->position);
                    if (!loop_body(n->c)) break;
                }
            } else if (kind == "delete") {
                std::shared_ptr < Array > values = array(n->a->binding);
                if (n->flag) {
                    std::string key = subscript(n->nodes);
                    values->erase(key);
                } else values->clear();
            } else if (kind == "next") {
                if (phase == "BEGIN" || phase == "END") throw Issue {n->position, "next used in BEGIN or END", 2};
                throw Transfer {"next", {} };
            } else if (kind == "exit") {
                if (n->a) exit_status = evaluate(n->a).to_number();
                throw Transfer {"exit", {} };
            } else if (kind == "return") {
                Value value = n->a ? evaluate(n->a) : Value {};
                throw Transfer {"return", value};
            } else throw Transfer {kind, {} };
        }
        std::optional<std::string> next_record() {
            while (true) {
                if (input_position < input_lines.size()) {
                    std::string line = input_lines[input_position++];
                    ++current->records;
                    cell({-1, "NR"})->scalar = Value::number(global("NR").to_number() + 1);
                    cell({-1, "FNR"})->scalar = Value::number(global("FNR").to_number() + 1);
                    return line;
                }
                if (operand_position == arguments.operands.size()) return std::nullopt;
                InputOperand& operand = arguments.operands[operand_position++];
                if (!operand.file) assign_input(operand.name, operand.value);
                else {
                    current = &operand;
                    input_lines = read_records(operand.name);
                    input_position = 0;
                    cell({-1, "FILENAME"})->scalar = Value::string(operand.name);
                    cell({-1, "FNR"})->scalar = Value::number(0);
                }
            }
        }
        void actions(const std::string& stage) {
            phase = stage;
            for (const NodePtr& rule : analysis.rules) if (rule->flavor == stage) {
                ++rule->count;
                statement(rule->a);
            }
        }
        bool matches(const NodePtr& rule) {
            if (rule->flavor == "all") return true;
            if (rule->flavor == "pattern") return evaluate(rule->nodes[0]).truth();
            if (!rule->inside && evaluate(rule->nodes[0]).truth()) rule->inside = true;
            if (!rule->inside) return false;
            if (evaluate(rule->nodes[1]).truth()) rule->inside = false;
            return true;
        }
        void records() {
            bool needed = false;
            for (const NodePtr& rule : analysis.rules) if (rule->flavor != "BEGIN") needed = true;
            if (!needed) return;
            phase = "records";
            while (true) {
                std::optional<std::string> line = next_record();
                if (!line) return;
                record.set(*line);
                try {
                    for (const NodePtr& rule : analysis.rules) if (rule->flavor != "BEGIN" && rule->flavor != "END" && matches(rule)) {
                        ++rule->count;
                        if (rule->a) statement(rule->a);
                        else streams.write(record.zero.to_string() + global("ORS").to_string());
                    }
                } catch (const Transfer& t) {
                    if (t.kind != "next") throw;
                }
            }
        }
        public:
        Engine(Analysis& a, Arguments args) : analysis(a), arguments(std::move(args)), record([this](const std::string& name) {
            return global(name);
        }) {
            for (const std::string& name : analysis.globals) {
                CellPtr value = cell({-1, name});
                if (analysis.arrays.count({-1, name})) value->array = std::make_shared < Array >();
            }
            for (const std::string& name : std::vector<std::string> {"FNR", "NR"}) cell({-1, name})->scalar = Value::number(0);
            cell({-1, "FILENAME"})->scalar = Value::string("");
            cell({-1, "FS"})->scalar = Value::string(" ");
            cell({-1, "OFS"})->scalar = Value::string(" ");
            cell({-1, "ORS"})->scalar = Value::string("\n");
            cell({-1, "SUBSEP"})->scalar = Value::string(std::string(1, 28));
            for (int line : analysis.lines) line_counts[line] = 0;
        }
        void execute() {
            try {
                for (const auto& option : arguments.options) assign_input(option.first, option.second);
                try {
                    actions("BEGIN");
                    records();
                } catch (const Transfer& t) {
                    if (t.kind != "exit") throw;
                }
                try {
                    actions("END");
                } catch (const Transfer& t) {
                    if (t.kind != "exit") throw;
                }
            } catch (const Issue& issue) {
                error = issue;
            }
        }
        void save() {
            streams.save();
            std::ofstream out("output/stats.txt");
            if (error) out << "status: runtime error at " << error->position.text() << ": " << error->message << '\n';
            else out << "status: exit " << exit_status << '\n';
            out << "[inputs]\n";
            for (const InputOperand& operand : arguments.operands) if (operand.file) out << operand.name << " records=" << operand.records << '\n';
            out << "[getline]\n";
            for (const std::string& name : streams.input_order) {
                const GetlineInput& source = streams.inputs.at(name);
                out << name << ' ' <<(source.ever ? "reads=" + std::to_string(source.reads) : "missing") << '\n';
            }
            out << "[rules]\n";
            for (const NodePtr& rule : analysis.rules) out << rule->position.text() << ' ' << rule->flavor << " count=" << rule->count << '\n';
            out << "[functions]\n";
            for (const NodePtr& f : analysis.functions) out << f->text << " calls=" << f->calls << " depth=" << f->depth << '\n';
            out << "[outputs]\nstdout.txt writes=" << streams.standard.writes << " bytes=" << streams.standard.content.size() << '\n';
            for (const std::string& name : streams.output_order) {
                const Output& output = streams.outputs.at(name);
                out << name << " writes=" << output.writes << " bytes=" << output.content.size() << '\n';
            }
            out << "[lines]\n";
            for (const auto& entry : line_counts) out << entry.first << " count=" << entry.second << '\n';
            out << "[globals]\n";
            for (const std::string& name : analysis.globals) {
                out << name << " = ";
                if (analysis.arrays.count({-1, name})) out << "array (" << array({-1, name})->size() << ')';
                else out << global(name).describe();
                out << '\n';
            }
        }
    };
}
int main() {
    using namespace awk;
    Arguments args = parse_arguments(read_file("input/args.txt"));
    try {
        std::vector<NodePtr> items = Parser(tokenize(read_file("input/program.awk"))).parse();
        Analysis analysis(std::move(items));
        Engine engine(analysis, std::move(args));
        engine.execute();
        engine.save();
    } catch (const Issue& issue) {
        std::ofstream standard("output/stdout.txt");
        std::ofstream out("output/stats.txt");
        if (issue.kind == 0) out << "status: syntax error at " << issue.position.text() << '\n';
        else out << "status: error at " << issue.position.text() << ": " << issue.message << '\n';
    }
}

#include "awk.hpp"
namespace awk {
    NodePtr node(const std::string& kind, const Position& position) {
        NodePtr value = std::make_shared < Node >();
        value->kind = kind;
        value->position = position;
        return value;
    }
    std::vector<NodePtr> children(const NodePtr& value) {
        std::vector<NodePtr> result;
        for (const NodePtr& child : {value->a, value->b, value->c, value->d}) if (child) result.push_back(child);
        result.insert(result.end(), value->nodes.begin(), value->nodes.end());
        return result;
    }
    bool is_lvalue(const NodePtr& value) {
        return value->kind == "name" || value->kind == "array" || value->kind == "field";
    }
    const Token& Parser::peek() const {return tokens[index];
    } Token Parser::take() {
        return tokens[index++];
    }
    bool Parser::accept(const std::string& spelling) {
        if (peek().text != spelling) return false;
        take();
        return true;
    }
    Token Parser::expect(const std::string& spelling) {
        if (peek().text != spelling) fail();
        return take();
    }
    [[noreturn]]void Parser::fail() const {throw Issue {peek().position, "", 0};
    } void Parser::newlines() {
        while (accept("\n")) {
        }
    }
    NodePtr Parser::name() {
        if (peek().kind != "name") fail();
        Token token = take();
        NodePtr result = node("name", token.position);
        result->text = token.text;
        return result;
    }
    std::vector<NodePtr> Parser::parse() {
        std::vector<NodePtr> items;
        while (peek().kind != "end") {
            if (accept("\n") || accept(";")) continue;
            Token start = peek();
            if (accept("function")) {
                if (peek().kind != "name" && peek().kind != "function_name") fail();
                Token token = take();
                NodePtr item = node("function", start.position);
                item->text = token.text;
                item->name_position = token.position;
                expect("(");
                if (peek().text != ")") do {
                    NodePtr parameter = name();
                    parameter->kind = "parameter";
                    item->nodes.push_back(parameter);
                    if (peek().text != ",") break;
                    take();
                    newlines();
                } while (true);
                expect(")");
                newlines();
                in_function = true;
                item->a = block();
                in_function = false;
                items.push_back(item);
                continue;
            }
            NodePtr item = node("rule", start.position);
            if (start.text == "BEGIN" || start.text == "END") item->flavor = take().text;
            else if (start.text == "{") item->flavor = "all";
            else {
                item->nodes.push_back(expression());
                if (accept(",")) {
                    newlines();
                    item->nodes.push_back(expression());
                }
                item->flavor = item->nodes.size() == 2 ? "range" : "pattern";
            }
            phase = item->flavor;
            if (phase == "BEGIN" || phase == "END" || phase == "all" || peek().text == "{") item->a = block();
            else if (peek().text != "\n" && peek().text != ";" && peek().kind != "end") fail();
            phase.clear();
            items.push_back(item);
        }
        return items;
    }
    NodePtr Parser::block() {
        Token t = expect("{");
        NodePtr result = node("block", t.position);
        while (peek().text != "}") {
            if (accept("\n") || accept(";")) continue;
            result->nodes.push_back(statement());
        }
        expect("}");
        return result;
    }
    NodePtr Parser::condition() {
        expect("(");
        NodePtr result = expression();
        expect(")");
        return result;
    }
    NodePtr Parser::loop_body() {
        newlines();
        ++loop_depth;
        NodePtr result = statement();
        --loop_depth;
        return result;
    }
    void Parser::terminator() {
        if (accept(";") || accept("\n")) return;
        if (peek().text != "}") fail();
    }
    NodePtr Parser::statement() {
        Token token = peek();
        const std::string spelling = token.text;
        if (spelling == "{") return block();
        if (accept(";")) return node("empty", token.position);
        NodePtr result = node(spelling, token.position);
        if (accept("if")) {
            result->a = condition();
            newlines();
            result->b = statement();
            newlines();
            if (accept("else")) {
                newlines();
                result->c = statement();
            }
            return result;
        }
        if (accept("while")) {
            result->a = condition();
            result->b = loop_body();
            return result;
        }
        if (accept("do")) {
            result->b = loop_body();
            newlines();
            expect("while");
            result->a = condition();
            terminator();
            return result;
        }
        if (accept("for")) {
            expect("(");
            if (index + 3 < tokens.size() && tokens[index].kind == "name" && tokens[index + 1].text == "in" && tokens[index + 2].kind == "name" && tokens[index + 3].text == ")") {
                result->kind = "for_in";
                result->a = name();
                expect("in");
                result->b = name();
                expect(")");
                result->c = loop_body();
                return result;
            }
            if (peek().text != ";") result->a = expression();
            expect(";");
            newlines();
            if (peek().text != ";") result->b = expression();
            expect(";");
            newlines();
            if (peek().text != ")") result->c = expression();
            expect(")");
            result->d = loop_body();
            return result;
        }
        if (spelling == "print" || spelling == "printf") {
            take();
            result = output(token);
        } else if (accept("delete")) {
            result->a = name();
            result->flag = accept("[");
            if (result->flag) {
                result->nodes = expression_list();
                expect("]");
            }
        } else if (spelling == "next" || spelling == "break" || spelling == "continue" || spelling == "exit" || spelling == "return") {
            take();
            if ((spelling == "next" && !in_function &&(phase == "BEGIN" || phase == "END")) ||(spelling == "return" && !in_function) ||((spelling == "break" || spelling == "continue") && loop_depth == 0)) throw Issue {token.position, "", 0};
            if ((spelling == "exit" || spelling == "return") && peek().text != ";" && peek().text != "\n" && peek().text != "}") result->a = expression();
        } else {
            result->kind = "expression_statement";
            result->a = expression();
        }
        terminator();
        return result;
    }
    bool Parser::parenthesized_output() const {if (peek().text != "(") return false;
    int depth = 0;
    for (std::size_t i = index;i < tokens.size();++i) {
        if (tokens[i].text == "(")++depth;
        else if (tokens[i].text == ")" && --depth == 0) {
            const Token& t = tokens[i + 1];
            return t.text == ";" || t.text == "\n" || t.text == "}" || t.text == ">" || t.text == ">>" || t.kind == "end";
        }
    }
    return false;
    } NodePtr Parser::output(Token token) {
        NodePtr result = node(token.text, token.position);
        if (parenthesized_output()) {
            expect("(");
            result->nodes = expression_list();
            expect(")");
        } else if (peek().text != ";" && peek().text != "\n" && peek().text != "}" && peek().text != ">" && peek().text != ">>") result->nodes = expression_list(false);
        if (token.text == "printf" && result->nodes.empty()) fail();
        if (peek().text == ">" || peek().text == ">>") {
            Token redirect = take();
            result->redirect = redirect.text;
            result->redirect_position = redirect.position;
            result->a = concatenation();
        }
        return result;
    }
    std::vector<NodePtr> Parser::expression_list(bool greater) {
        std::vector<NodePtr> result = {expression(greater)};
        while (accept(",")) {
            newlines();
            result.push_back(expression(greater));
        }
        return result;
    }
    NodePtr Parser::expression(bool greater) {
        NodePtr left = conditional(greater);
        const std::set<std::string> assignments = {"=", "+=", "-=", "*=", "/=", "%=", "^="};
        if (is_lvalue(left) && assignments.count(peek().text)) {
            Token op = take();
            NodePtr result = node("assignment", op.position);
            result->text = op.text;
            result->a = left;
            result->b = expression(greater);
            return result;
        }
        return left;
    }
    NodePtr Parser::conditional(bool greater) {
        NodePtr left = logical(0, greater);
        if (!accept("?")) return left;
        NodePtr result = node("conditional", tokens[index - 1].position);
        result->a = left;
        result->b = conditional(greater);
        expect(":");
        result->c = conditional(greater);
        return result;
    }
    NodePtr Parser::binary(Token op, NodePtr a, NodePtr b) {
        NodePtr result = node("binary", op.position);
        result->text = op.text;
        result->a = std::move(a);
        result->b = std::move(b);
        return result;
    }
    NodePtr Parser::logical(int level, bool greater) {
        if (level == 2) return membership(greater);
        NodePtr left = logical(level + 1, greater);
        std::string op = level == 0 ? "||" : "&&";
        while (peek().text == op) {
            Token token = take();
            newlines();
            NodePtr right = logical(level + 1, greater);
            left = binary(token, left, right);
        }
        return left;
    }
    NodePtr Parser::membership(bool greater) {
        NodePtr left = comparison(greater);
        while (peek().text == "in") {
            Token token = take();
            NodePtr result = node("membership", token.position);
            result->nodes = {left};
            result->a = name();
            left = result;
        }
        return left;
    }
    NodePtr Parser::comparison(bool greater) {
        NodePtr left = concatenation();
        const std::set<std::string> ops = {"<", "<=", "==", "!=", ">=", ">"};
        while (ops.count(peek().text) &&(greater || peek().text != ">")) {
            Token op = take();
            NodePtr right = concatenation();
            left = binary(op, left, right);
        }
        return left;
    }
    NodePtr Parser::concatenation() {
        NodePtr left = additive();
        while (peek().kind == "number" || peek().kind == "string" || peek().kind == "name" || peek().kind == "function_name" || peek().kind == "builtin" || peek().text == "$" || peek().text == "(" || peek().text == "++" || peek().text == "--") {
            Token op = peek();
            op.text = "concat";
            NodePtr right = additive();
            left = binary(op, left, right);
        }
        return left;
    }
    NodePtr Parser::additive() {
        NodePtr left = multiplicative();
        while (peek().text == "+" || peek().text == "-") {
            Token op = take();
            NodePtr right = multiplicative();
            left = binary(op, left, right);
        }
        return left;
    }
    NodePtr Parser::multiplicative() {
        NodePtr left = unary();
        while (peek().text == "*" || peek().text == "/" || peek().text == "%") {
            Token op = take();
            NodePtr right = unary();
            left = binary(op, left, right);
        }
        return left;
    }
    NodePtr Parser::unary() {
        if (peek().text == "!" || peek().text == "-" || peek().text == "+") {
            Token op = take();
            NodePtr result = node("unary", op.position);
            result->text = op.text;
            result->a = unary();
            return result;
        }
        NodePtr left = postfix();
        if (peek().text == "^") {
            Token op = take();
            NodePtr right = unary();
            left = binary(op, left, right);
        }
        return left;
    }
    NodePtr Parser::prefix() {
        Token op = take();
        NodePtr result = node("increment", op.position);
        result->number = op.text == "++" ? 1 : -1;
        result->flag = true;
        result->a = lvalue();
        return result;
    }
    NodePtr Parser::postfix() {
        if (peek().text == "++" || peek().text == "--") return prefix();
        NodePtr left = atom();
        if (is_lvalue(left) &&(peek().text == "++" || peek().text == "--")) {
            Token op = take();
            NodePtr result = node("increment", op.position);
            result->number = op.text == "++" ? 1 : -1;
            result->a = left;
            return result;
        }
        return left;
    }
    NodePtr Parser::lvalue() {
        if (peek().kind == "name") {
            NodePtr result = name();
            if (accept("[")) {
                result->kind = "array";
                result->nodes = expression_list();
                expect("]");
            }
            return result;
        }
        if (peek().text == "$") {
            Token dollar = take();
            NodePtr result = node("field", dollar.position);
            result->a =(peek().text == "++" || peek().text == "--") ? prefix() : atom();
            return result;
        }
        fail();
    }
    NodePtr Parser::atom() {
        Token token = peek();
        if (token.kind == "number" || token.kind == "string") {
            take();
            NodePtr result = node(token.kind, token.position);
            if (token.kind == "number") result->number = std::stoll(token.value);
            else result->text = token.value;
            return result;
        }
        if (token.kind == "name" || token.text == "$") return lvalue();
        if (accept("(")) {
            std::vector<NodePtr> values = expression_list();
            expect(")");
            if (values.size() == 1) {
                NodePtr result = node("paren", token.position);
                result->a = values[0];
                return result;
            }
            expect("in");
            NodePtr result = node("membership", token.position);
            result->nodes = values;
            result->a = name();
            return result;
        }
        if (token.kind == "function_name" || token.kind == "builtin") {
            take();
            NodePtr result = node(token.kind == "builtin" ? "builtin" : "call", token.position);
            result->text = token.text;
            if (accept("(")) {
                if (peek().text != ")") result->nodes = expression_list();
                expect(")");
            } else if (token.kind == "function_name" || token.text != "length") fail();
            if (result->kind == "builtin") {
                std::size_t n = result->nodes.size();
                bool valid = token.text == "length" ? n <= 1 : token.text == "substr" || token.text == "split" ? n == 2 || n == 3 : token.text == "index" ? n == 2 : token.text == "sprintf" ? n >= 1 : n == 1;
                if (!valid ||(token.text == "split" && result->nodes[1]->kind != "name")) throw Issue {token.position, "", 0};
            }
            return result;
        }
        if (accept("getline")) {
            NodePtr result = node("getline", token.position);
            if (peek().kind == "name" || peek().text == "$") result->a = lvalue();
            if (accept("<")) result->b = atom();
            return result;
        }
        fail();
    }
}

#include "awk.hpp"
namespace awk {
    std::string read_file(const std::string& path) {
        std::ifstream input(path);
        return std::string(std::istreambuf_iterator < char >(input), std::istreambuf_iterator < char >());
    }
    static bool valid_name(const std::string& name) {
        if (name.empty() || !letter(name[0])) return false;
        for (char c : name) if (!letter(c) && !digit(c)) return false;
        return true;
    }
    bool valid_filename(const std::string& name) {
        if (name.empty() || name[0] == '.') return false;
        for (char c : name) if (!letter(c) && !digit(c) && c != '.' && c != '-') return false;
        return true;
    }
    Arguments parse_arguments(const std::string& text) {
        Arguments args;
        std::istringstream input(text);
        std::string line;
        while (std::getline(input, line)) {
            if (line.compare(0, 3, "-F ") == 0) args.options.emplace_back("FS", line.substr(3));
            else if (line.compare(0, 3, "-v ") == 0) {
                std::size_t at = line.find('=', 3);
                args.options.emplace_back(line.substr(3, at - 3), line.substr(at + 1));
            } else {
                std::size_t at = line.find('=');
                if (at != std::string::npos && valid_name(line.substr(0, at))) args.operands.push_back({false, line.substr(0, at), line.substr(at + 1), 0});
                else args.operands.push_back({true, line, "", 0});
            }
        }
        return args;
    }
    std::vector<std::string> read_records(const std::string& name) {
        std::ifstream input("input/" + name);
        std::vector<std::string> result;
        std::string line;
        while (std::getline(input, line)) result.push_back(line);
        return result;
    }
    void Streams::write(const std::string& text, const std::optional<std::string>& name, const std::string& mode, Position position) {
        if (!name) {
            standard.content += text;
            ++standard.writes;
            return;
        }
        if (!valid_filename(*name) || *name == "stdout.txt" || *name == "stats.txt") throw Issue {position, "invalid output file name", 2};
        if (!outputs.count(*name)) output_order.push_back(*name);
        Output& out = outputs[*name];
        if (!out.open) {
            out.open = true;
            if (mode == ">") out.content.clear();
        }
        out.content += text;
        ++out.writes;
    }
    std::pair<int, std::string> Streams::getline(const std::string& name) {
        if (!inputs.count(name)) input_order.push_back(name);
        GetlineInput& source = inputs[name];
        if (!source.open) {
            if (!valid_filename(name)) return {-1, ""};
            std::ifstream input("input/" + name);
            if (!input) return {-1, ""};
            source.lines = read_records(name);
            source.position = 0;
            source.open = source.ever = true;
        }
        if (source.position == source.lines.size()) return {0, ""};
        ++source.reads;
        return {1, source.lines[source.position++]};
    }
    int Streams::close(const std::string& name) {
        bool closed = false;
        std::map<std::string, Output>::iterator out = outputs.find(name);
        if (out != outputs.end() && out->second.open) {
            out->second.open = false;
            closed = true;
        }
        std::map<std::string, GetlineInput>::iterator in = inputs.find(name);
        if (in != inputs.end() && in->second.open) {
            in->second.open = false;
            closed = true;
        }
        return closed ? 0 : -1;
    }
    void Streams::save() const {std::ofstream standard_file("output/stdout.txt");
    standard_file << standard.content;
    for (const auto& entry : outputs) {
        std::ofstream out("output/" + entry.first);
        out << entry.second.content;
    }
    }
}

#include "awk.hpp"
namespace awk {
    static bool whitespace(char c) {
        return c == ' ' || c == '\t' || c == '\n';
    }
    static Integer numeric_prefix(const std::string& s) {
        std::size_t i = 0;
        while (i < s.size() && whitespace(s[i]))++i;
        int sign = 1;
        if (i < s.size() &&(s[i] == '+' || s[i] == '-')) {
            if (s[i] == '-') sign = -1;
            ++i;
        }
        Integer value = 0;
        while (i < s.size() && digit(s[i])) value = value * 10 + s[i++] - '0';
        return sign * value;
    }
    Value Value::number(Integer n) {
        Value result;
        result.kind = Kind::Number;
        result.numeric = n;
        return result;
    }
    Value Value::string(const std::string& s) {
        Value result;
        result.kind = Kind::String;
        result.text = s;
        return result;
    }
    Value Value::input(const std::string& s) {
        Value result = string(s);
        std::size_t first = 0, last = s.size();
        while (first < last && whitespace(s[first]))++first;
        while (last > first && whitespace(s[last - 1]))--last;
        if (first < last &&(s[first] == '+' || s[first] == '-'))++first;
        bool numeric = first < last;
        for (std::size_t i = first;i < last;++i) if (!digit(s[i])) numeric = false;
        if (numeric) {
            result.kind = Kind::NumericString;
            result.numeric = numeric_prefix(s);
        }
        return result;
    }
    Integer Value::to_number() const {return kind == Kind::String ? numeric_prefix(text) : numeric;
    } std::string Value::to_string() const {return kind == Kind::Number ? std::to_string(numeric) : kind == Kind::Uninitialized ? "" : text;
    } bool Value::truth() const {return kind == Kind::String ? !text.empty() : numeric != 0;
    } std::string Value::describe() const {if (kind == Kind::Number) return std::to_string(numeric);
    if (kind == Kind::Uninitialized) return "(uninitialized)";
    std::ostringstream out;
    out << '"';
    for (unsigned char c : text) {
        if (c == '"') out << "\\\"";
        else if (c == '\\') out << "\\\\";
        else if (c == '\n') out << "\\n";
        else if (c == '\t') out << "\\t";
        else if (c >= 32 && c <= 126) out << c;
        else out << '\\' << std::oct << std::setw(3) << std::setfill('0') << static_cast<int>(c) << std::dec;
    }
    out << '"';
    if (kind == Kind::NumericString) out << " (strnum)";
    return out.str();
    } int compare(const Value& a, const Value& b) {
        if (a.kind != Value::Kind::String && b.kind != Value::Kind::String) {
            Integer x = a.to_number(), y = b.to_number();
            return(x > y) -(x < y);
        }
        std::string x = a.to_string(), y = b.to_string();
        return(x > y) -(x < y);
    }
    static bool integer_subscript(const std::string& s) {
        if (s == "0") return true;
        std::size_t i = !s.empty() && s[0] == '-' ? 1 : 0;
        if (i == s.size() || s[i] < '1' || s[i] > '9') return false;
        for (++i;i < s.size();++i) if (!digit(s[i])) return false;
        return true;
    }
    bool subscript_less(const std::string& a, const std::string& b) {
        bool ai = integer_subscript(a), bi = integer_subscript(b);
        if (ai != bi) return ai;
        if (ai) return std::stoll(a) < std::stoll(b);
        return a < b;
    }
    std::vector<std::string> split_pieces(const std::string& text, const std::string& separator) {
        std::vector<std::string> result;
        if (text.empty()) return result;
        if (separator.empty()) {
            for (char c : text) result.emplace_back(1, c);
            return result;
        }
        if (separator == " ") {
            std::size_t i = 0;
            while (i < text.size()) {
                while (i < text.size() && whitespace(text[i]))++i;
                std::size_t start = i;
                while (i < text.size() && !whitespace(text[i]))++i;
                if (i > start) result.push_back(text.substr(start, i - start));
            }
            return result;
        }
        std::size_t start = 0;
        while (true) {
            std::size_t next = text.find(separator, start);
            if (next == std::string::npos) {
                result.push_back(text.substr(start));
                break;
            }
            result.push_back(text.substr(start, next - start));
            start = next + separator.size();
        }
        return result;
    }
    void Record::set(const std::string& text) {
        zero = Value::input(text);
        fields.clear();
        for (const std::string& piece : split_pieces(text, special("FS").to_string())) fields.push_back(Value::input(piece));
    }
    Value Record::read(Integer index) const {return index == 0 ? zero : index <= static_cast<Integer>(fields.size()) ? fields[static_cast<std::size_t>(index - 1)] : Value {};
    } void Record::rebuild() {
        std::string text, separator = special("OFS").to_string();
        for (std::size_t i = 0;i < fields.size();++i) {
            if (i) text += separator;
            text += fields[i].to_string();
        }
        zero = Value::input(text);
    }
    void Record::write(Integer index, const Value& value) {
        if (index == 0) {
            set(value.to_string());
            return;
        }
        if (index > static_cast<Integer>(fields.size())) fields.resize(static_cast<std::size_t>(index), Value::string(""));
        fields[static_cast<std::size_t>(index - 1)] = value;
        rebuild();
    }
    void Record::resize(Integer size) {
        fields.resize(static_cast<std::size_t>(size), Value::string(""));
        rebuild();
    }
}
